import {colours,growth,escapeHTML as esc,selectRepos,plantSVG} from './garden.js';
const $=s=>document.querySelector(s),demoNames=['tiny-adventures','pixel-pals','weekend-weather','my-first-api','garden-notes','borrowed-magic'];
const demo=demoNames.map((name,i)=>({id:i,name,language:['TypeScript','Python','JavaScript','Go','HTML','Rust'][i],description:['A tiny world for big imaginations.','Little pixel friends, made with love.','A sunny little weather dashboard.','Learning how to bring an API to life.','Notes from a curious developer.','A fork worth making your own.'][i],stargazers_count:[32,12,6,0,3,9][i],forks_count:[4,2,1,0,0,2][i],open_issues_count:[2,0,1,0,0,3][i],fork:i===5,archived:false,created_at:new Date(Date.now()-[400,240,90,12,40,190][i]*86400000).toISOString(),updated_at:new Date(Date.now()-i*86400000).toISOString(),html_url:null}));
let repos=demo,filter='all',sort='updated',isDemo=true,controller;
function render(){const shown=selectRepos(repos,filter,sort);$('#plants').innerHTML=shown.length?shown.map(r=>`<button class="plant" data-id="${r.id}" aria-label="Inspect ${esc(r.name)}">${plantSVG(r)}<div class="plant-name">${esc(r.name)}</div><div class="plant-meta"><span style="color:${colours[r.language]||colours.Unknown}">●</span> ${esc(r.language||'Unknown')} · ☆ ${r.stargazers_count}${r.fork?' · fork':''}</div></button>`).join(''):'<div class="empty">No plants in this patch yet. Try another filter, or explore the demo.</div>';$('#count').textContent=`${shown.length} repositories planted`;const stars=repos.reduce((a,r)=>a+r.stargazers_count,0),issues=repos.reduce((a,r)=>a+r.open_issues_count,0),langs=new Set(repos.map(r=>r.language).filter(Boolean)).size;$('#stats').innerHTML=[[repos.length,'PLANTS IN YOUR GARDEN'],[stars,'STARS / BLOSSOMS'],[langs,'LANGUAGE VARIETIES'],[issues,'OPEN ISSUES + PULL REQUESTS']].map(([v,label])=>`<div class="stat"><strong>${v.toLocaleString()}</strong><span>${label}</span></div>`).join('');}
function showDetail(r){const stage=growth(r),quote=r.archived?'Taking a well-earned rest. Old roots still count.':r.fork?'A transplant! Make yourself at home.':r.stargazers_count>10?'Look at these blossoms. Someone likes what you’re growing.':stage===0?'Just getting started. Even the biggest trees began here.':r.open_issues_count>0?'A few bugs in the garden. All part of the adventure.':'Quietly growing. No rush, gardener.';$('#detail-body').innerHTML=`<div class="portrait">${plantSVG(r)}</div><p class="eyebrow">${['SEEDLING','GROWING','ESTABLISHED'][stage]} · ${esc(r.language||'UNKNOWN LANGUAGE')}</p><h2 class="detail-name">${esc(r.name)}</h2><p class="detail-desc">${esc(r.description||'A little mystery growing in your garden.')}</p><p class="quote">“${quote}”</p><p class="detail-desc">☆ ${r.stargazers_count} stars · ${r.forks_count} forks<br>${r.open_issues_count} open issues + pull requests<br>Last tended ${new Date(r.updated_at).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})}</p>${r.html_url?`<a class="repo-link" href="${esc(r.html_url)}" target="_blank" rel="noopener noreferrer">Visit repository ↗</a>`:'<p class="muted">An imaginary plant in the demo garden.</p>'}`;$('#detail').showModal();}
$('#plants').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b){const r=repos.find(r=>String(r.id)===b.dataset.id);if(r)showDetail(r);}});
$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
$('.filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render();};$('#sort').onchange=e=>{sort=e.target.value;render();};
$('#shuffle').onclick=()=>{const container=$('#plants'),nodes=[...container.children];for(let i=nodes.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[nodes[i],nodes[j]]=[nodes[j],nodes[i]];}nodes.forEach(n=>container.append(n));};
$('#theme').onclick=()=>{const night=document.body.classList.toggle('night');$('#theme').textContent=night?'☀ Day garden':'☾ Night garden';try{localStorage.setItem('gitgarden-night',night?'1':'0');}catch{}};try{if(localStorage.getItem('gitgarden-night')==='1')$('#theme').click();}catch{}
function resetFilter(){filter='all';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));}
$('#demo').onclick=()=>{controller?.abort();repos=demo;isDemo=true;resetFilter();$('#owner').textContent='THE COMMUNITY PLOT';$('#garden-title').textContent='A little inspiration';$('#mode').textContent='DEMO GARDEN';$('#message').textContent='Six imaginary repositories, just to show what can grow.';$('#grow').disabled=false;$('#grow').innerHTML='Grow my garden <span>↗</span>';render();};
async function grow(username){controller?.abort();const current=new AbortController();controller=current;$('#grow').disabled=true;$('#grow').textContent='Planting…';$('#message').textContent='Gathering your public repositories…';const timeout=setTimeout(()=>current.abort(),20000);try{let all=[],capped=false;for(let page=1;page<=3;page++){const response=await fetch(`https://api.github.com/users/${encodeURIComponent(username)}/repos?type=owner&sort=updated&per_page=100&page=${page}`,{signal:current.signal,headers:{Accept:'application/vnd.github+json'}});if(!response.ok)throw new Error(response.status===404?'That GitHub username wasn’t found. Check the spelling and try again.':response.status===403||response.status===429?'GitHub’s public request limit was reached. Try again later, or enjoy the demo garden.':`GitHub returned an error (${response.status}). Please try again.`);const data=await response.json();if(!Array.isArray(data))throw new Error('GitHub sent an unexpected response. Please try again.');all.push(...data);if(data.length<100)break;if(page===3)capped=true;}if(controller!==current)return;repos=all;isDemo=false;resetFilter();$('#owner').textContent=`@${username.toUpperCase()}’S PUBLIC PLOT`;$('#garden-title').textContent=`${username}’s garden`;$('#mode').textContent='LIVE GITHUB DATA';$('#message').textContent=all.length?`Planted ${all.length} public repositories.${capped?' Showing up to 300 most recently updated repositories.':''}`:'No public repositories yet. Your garden is ready for its first seed.';render();history.replaceState(null,'',`?user=${encodeURIComponent(username)}`);}catch(e){if(controller!==current)return;$('#message').textContent=e.name==='AbortError'?'The request took too long. Try again, or explore the demo.':e.message||'Could not reach GitHub. Check your connection or try the demo.';}finally{clearTimeout(timeout);if(controller===current){$('#grow').disabled=false;$('#grow').innerHTML='Grow my garden <span>↗</span>';}}}
$('#search').onsubmit=e=>{e.preventDefault();const name=$('#username').value.trim();if(!/^[a-z\d](?:[a-z\d-]{0,37}[a-z\d])?$/i.test(name)||name.includes('--')){$('#message').textContent='Use a GitHub username: letters, numbers, and single hyphens.';return;}grow(name);};
$('#how').onclick=()=>{$('#detail-body').innerHTML='<p class="eyebrow">A FIELD GUIDE</p><h2>How your garden grows</h2><p class="detail-desc">Each public repository becomes a plant. Its age sets its growth stage: under 30 days is a seedling, under 180 days is growing, and older repositories are established.</p><p class="detail-desc">Stars add blossoms (up to five). Programming language sets their colour. Forks get sage pots. A little insect appears when GitHub reports open issues or pull requests.</p><p class="quote">These are playful metaphors, never a judgement of your code.</p><p class="detail-desc">This version reads public repository metadata directly from GitHub. It does not read private repositories, commits, test results, or merged PRs. No tokens or sign-in required. GitHub limits unauthenticated requests. Profiles with many repositories show up to 300.</p>';$('#detail').showModal();};
render();const initial=new URLSearchParams(location.search).get('user');if(initial&&/^[a-z\d](?:[a-z\d-]{0,37}[a-z\d])?$/i.test(initial)&&!initial.includes('--')){$('#username').value=initial;grow(initial);}
